 NOT NULL) AS `pressure_nonnull`,SUM(`radiation` IS NOT NULL) AS `radiation_nonnull`,SUM(`rain` IS NOT NULL) AS `rain_nonnull`,SUM(`rainDur` IS NOT NULL) AS `rainDur_nonnull`,SUM(`rainRate` IS NOT NULL) AS `rainRate_nonnull`,SUM(`soilad1` IS NOT NULL) AS `soilad1_nonnull`,SUM(`soilMoist1` IS NOT NULL) AS `soilMoist1_nonnull`,SUM(`soilMoistBatt1` IS NOT NULL) AS `soilMoistBatt1_nonnull`,SUM(`soilTemp1` IS NOT NULL) AS `soilTemp1_nonnull`,SUM(`soilTemp2` IS NOT NULL) AS `soilTemp2_nonnull`,SUM(`soilTemp3` IS NOT NULL) AS `soilTemp3_nonnull`,SUM(`soilTemp4` IS NOT NULL) AS `soilTemp4_nonnull`,SUM(`soilTemp5` IS NOT NULL) AS `soilTemp5_nonnull`,SUM(`soilTemp6` IS NOT NULL) AS `soilTemp6_nonnull`,SUM(`sunshine_time` IS NOT NULL) AS `sunshine_time_nonnull`,SUM(`sunshineDur` IS NOT NULL) AS `sunshineDur_nonnull`,SUM(`UV` IS NOT NULL) AS `UV_nonnull`,SUM(`vpd` IS NOT NULL) AS `vpd_nonnull`,SUM(`wbgt` IS NOT NULL) AS `wbgt_nonnull`,SUM(`wh26_rssi` IS NOT NULL) AS `wh26_rssi_nonnull`,SUM(`wh31_ch1_rssi` IS NOT NULL) AS `wh31_ch1_rssi_nonnull`,SUM(`wh31_ch1_sig` IS NOT NULL) AS `wh31_ch1_sig_nonnull`,SUM(`wh31_ch2_sig` IS NOT NULL) AS `wh31_ch2_sig_nonnull`,SUM(`wh40_rssi` IS NOT NULL) AS `wh40_rssi_nonnull`,SUM(`wh41_ch1_rssi` IS NOT NULL) AS `wh41_ch1_rssi_nonnull`,SUM(`wh51_ch1_rssi` IS NOT NULL) AS `wh51_ch1_rssi_nonnull`,SUM(`wh51_ch1_sig` IS NOT NULL) AS `wh51_ch1_sig_nonnull`,SUM(`wh57_rssi` IS NOT NULL) AS `wh57_rssi_nonnull`,SUM(`windchill` IS NOT NULL) AS `windchill_nonnull`,SUM(`windDir` IS NOT NULL) AS `windDir_nonnull`,SUM(`windGust` IS NOT NULL) AS `windGust_nonnull`,SUM(`windGustDir` IS NOT NULL) AS `windGustDir_nonnull`,SUM(`windrun` IS NOT NULL) AS `windrun_nonnull`,SUM(`windSpeed` IS NOT NULL) AS `windSpeed_nonnull`,SUM(`ws80_batt` IS NOT NULL) AS `ws80_batt_nonnull`,SUM(`ws80_rssi` IS NOT NULL) AS `ws80_rssi_nonnull`,SUM(`ws80_sig` IS NOT NULL) AS `ws80_sig_nonnull`,SUM(`outEquiTemp` IS NOT NULL) AS `outEquiTemp_nonnull`,SUM(`GTS` IS NOT NULL) AS `GTS_nonnul